import { tags } from "typia";

/**
 * Completion trend indicators analyzing the direction and strength of task
 * completion patterns over time.
 *
 * This entity provides directional analysis of productivity trends, helping
 * users understand whether their task completion habits are improving,
 * declining, or remaining stable. Trend analysis supports behavioral change and
 * productivity optimization efforts.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ICompletionTrend = {
  /**
   * General trend direction based on completion pattern analysis, indicating
   * whether daily productivity is increasing, decreasing, or remaining stable
   * over the analysis timeframe.
   */
  direction: "increasing" | "decreasing" | "stable";

  /**
   * Percentage change in average daily completions when comparing recent week
   * to the week before, providing quantitative measure of trend strength and
   * direction.
   */
  weekly_average_change_percent?:
    | (number & tags.Minimum<-100> & tags.Maximum<100>)
    | undefined;

  /**
   * Normalized score (0-100) indicating the consistency of daily task
   * completion activity, where higher scores indicate more regular completion
   * patterns with less day-to-day variation.
   */
  consistency_score?:
    | (number & tags.Minimum<0> & tags.Maximum<100>)
    | undefined;
};
